using System.Security.Claims;
using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Authorization;
using Microsoft.AspNetCore.Components.Web;
using sv_ee4589a834e542ad8321ffd224b71ca1.Client.Auth;

namespace sv_ee4589a834e542ad8321ffd224b71ca1.Auth;

/// <summary>
/// Server-side AuthenticationStateProvider that simulates a logged-in user
/// and persists auth state so the WebAssembly client can pick it up after
/// the interactive runtime activates.
/// </summary>
public sealed class ServerAuthenticationStateProvider : AuthenticationStateProvider, IHostEnvironmentAuthenticationStateProvider, IDisposable
{
    private static readonly AuthenticationState _authState;
    private readonly PersistentComponentState _persistentState;
    private readonly PersistingComponentStateSubscription _subscription;
    private Task<AuthenticationState>? _authStateTask;

    static ServerAuthenticationStateProvider()
    {
        var claims = new List<Claim>
        {
            new(ClaimTypes.Name, "bob@example.com"),
            new(ClaimTypes.Email, "bob@example.com"),
            new(ClaimTypes.Role, "User"),
            new(ClaimTypes.Role, "Editor"),
        };

        var identity = new ClaimsIdentity(claims, authenticationType: "Hardcoded");
        _authState = new AuthenticationState(new ClaimsPrincipal(identity));
    }

    public ServerAuthenticationStateProvider(PersistentComponentState persistentState)
    {
        _persistentState = persistentState;
        _subscription = _persistentState.RegisterOnPersisting(OnPersistingAsync, RenderMode.InteractiveWebAssembly);
    }

    public override Task<AuthenticationState> GetAuthenticationStateAsync()
        => _authStateTask ?? Task.FromResult(_authState);

    public void SetAuthenticationState(Task<AuthenticationState> authenticationStateTask)
    {
        _authStateTask = authenticationStateTask;
    }

    private Task OnPersistingAsync()
    {
        var principal = _authState.User;
        var userInfo = new UserInfo
        {
            Email = principal.FindFirstValue(ClaimTypes.Email)!,
            Roles = principal.FindAll(ClaimTypes.Role).Select(c => c.Value).ToArray(),
        };

        _persistentState.PersistAsJson(nameof(UserInfo), userInfo);
        return Task.CompletedTask;
    }

    public void Dispose()
    {
        _subscription.Dispose();
    }
}

